import { test, expect } from "@playwright/test";

const APP = process.env.GENCLASS_APP_URL ?? "http://localhost:3000";
const SCHEDULE = {"order":"seeded","seed":2,"delay":{"minMs":0,"maxMs":600},"maxHoldMs":2100};

test("/posts/create: the final state does not depend on response order (GenClass f1)", async ({ page }) => {
